wsc:message.wsc:body:
#[%dw 2.0
output application/xml
ns ns0 http://aeeph.com/routeservice
var queryParams = attributes.queryParams default {}
fun normalizeValue(val) =
    if (val is Array)
        (val map ((item) -> item as String) joinBy ",")
    else
        val
// Параметры фильтрации (все, кроме служебных и _op параметров)
var filterParams = queryParams filterObject ((value, key) -> 
    !(key startsWith "filter[") and
    !(key startsWith "operation[") and
    !(key startsWith "operations[") and
    key != "page" and
    key != "pageSize" and
    key != "sort" and
    !(key endsWith "_op")
)
// Параметры операций (все, что заканчивается на _op)
var operationParams = queryParams filterObject ((value, key) -> 
    !(key startsWith "operation[") and
    !(key startsWith "operations[") and
    (key endsWith "_op")
)
// Создаем список фильтров
var filters = filterParams pluck ((value, key) -> {
    keyName: key,
    value: normalizeValue(value)
})
// Создаем список операций
var operations = operationParams pluck ((value, key) -> {
    keyName: key replace "_op" with "",
    value: normalizeValue(value)
})
var pageValue =
    if (queryParams.page?)
        (normalizeValue(queryParams.page) as Number)
    else
        null
var pageSizeValue =
    if (queryParams.pageSize?)
        (normalizeValue(queryParams.pageSize) as Number)
    else
        null
---
do {
    var soapRequest = {
        ns0#GetRoutesRequest: {
            (ns0#sort: normalizeValue(queryParams.sort)) if (queryParams.sort? and queryParams.sort != null),
            (ns0#filters: {
                (filters map ((item) -> { 
                    ns0#filter @(key: item.keyName): item.value default "" 
                }))
            }) if (sizeOf(filters) > 0),
            (ns0#operations: {
                (operations map ((item) -> { 
                    ns0#operation @(key: item.keyName): item.value default "" 
                }))
            }) if (sizeOf(operations) > 0),
            (ns0#page: pageValue) if (pageValue != null),
            (ns0#pageSize: pageSizeValue) if (pageSizeValue != null)
        }
    }
    var logMsg = "SOAP Request - Filters: " ++ sizeOf(filters) ++ ", Operations: " ++ sizeOf(operations) ++ ", Request: " ++ write(soapRequest, 'application/xml')
    ---
    log(logMsg) then soapRequest
}]

ee:message.ee:set-payload:
%dw 2.0
output application/xml
import modules::routeUtils as RouteUtils
ns ns0 http://aeeph.com/routeservice
var soapResponse = payload.body.ns0#GetRoutesResponse
var routesContainer = soapResponse.ns0#routes
var routes = routesContainer.*ns0#route default []
---
do {
    var logMessage = "Routes data type: " ++ typeOf(routes) ++ ", size: " ++ sizeOf(routes) ++ ", routes: " ++ write(routes, 'application/json', {'indent': false})
    ---
    log(logMessage) then {
        RouteList: {
            Route: RouteUtils::soapRoutesToRest(routes)
        }
    }
}

