output application/xml
import modules::routeUtils as RouteUtils
ns ns0 http://aeeph.com/routeservice
var routeId = vars.routeId
var inputPayload = payload
---
do {
    var soapReq = {
        ns0#UpdateRouteRequest:
            ({
                ns0#id: routeId as Number
            }
            ++ RouteUtils::buildRouteFields(inputPayload))
    }
    var logMsg = "Update SOAP Request for ID: " ++ routeId ++ ", XML: " ++ write(soapReq, 'application/xml')
    ---
    log(logMsg) then soapReq
}

