ns ns0 http://aeeph.com/routeservice
var distancesContainer = payload.body.ns0#GetUniqueDistancesResponse.ns0#distances
var distances = distancesContainer.*ns0#distance default []
---
{
    DistanceList: {
        Distance: if (distances is Array) 
                    distances map ((item) -> item as Number)
                  else if (distances is Object or distances is String or distances is Number)
                    [distances as Number]
                  else
                    []
    }
}

